@org.springframework.boot.webmvc.test.autoconfigure.AutoConfigureMockMvc
class MomentIntegrationTest extends AbstractPostgresIntegrationTest {
 @Autowired org.springframework.test.web.servlet.MockMvc http;
 @Autowired com.wedo.backend.security.jwt.JwtService jwt;
 @Autowired MomentService service; @Autowired UserRepository users; @Autowired GroupRepository groups;
 @Autowired GroupMembershipRepository members; @Autowired ActivityRepository activities;
 @Autowired JdbcTemplate db; @Autowired PlatformTransactionManager transactions;
 @Autowired MediaReferenceService refs; @Autowired UploadService uploads; @Autowired DomainRealtimeCoordinator realtime;
 @MockitoBean ObjectStorageService storage;
 record F(UUID group,UUID activity,UUID owner,UUID member,UUID outsider){}
 F fixture(){Instant n=Instant.now();UUID o=user(),m=user(),x=user(),g=UUID.randomUUID(),a=UUID.randomUUID();groups.save(new GroupEntity(g,"R4 isolated",null,null,GroupStatus.ACTIVE,o,n,n));members.save(new GroupMembershipEntity(UUID.randomUUID(),g,o,GroupRole.OWNER,GroupMembershipStatus.ACTIVE,n,null));members.save(new GroupMembershipEntity(UUID.randomUUID(),g,m,GroupRole.MEMBER,GroupMembershipStatus.ACTIVE,n,null));activities.save(new ActivityEntity(a,g,o,"Memory Activity",null,ActivityStatus.COMPLETED,null,null,null,null,null,n,n));return new F(g,a,o,m,x);}
 UUID user(){UUID u=UUID.randomUUID();Instant n=Instant.now();users.save(new UserEntity(u,u+"@r4.test","u"+u.toString().substring(0,8),"QA memory",UserStatus.ACTIVE,n,n));return u;}
 String key(F f,UUID uploader,boolean video){String k=refs.newKey(video?UploadCategory.MOMENT_VIDEO:UploadCategory.MOMENT_IMAGE,f.group(),uploader);String file=video?"clip.mp4":"photo.png";when(storage.head(k)).thenReturn(new ObjectStorageService.ObjectMetadata(video?"video/mp4":"image/png",42,Map.of("declared-size","42","original-file-name",Base64.getUrlEncoder().withoutPadding().encodeToString(file.getBytes(java.nio.charset.StandardCharsets.UTF_8)))));when(storage.presignGet(eq(k),any())).thenReturn(new ObjectStorageService.PresignedObject("https://storage.test/private",Instant.now().plusSeconds(60),Map.of()));return k;}
 Moment create(F f){return service.create(f.group(),f.member(),new CreateMoment(UUID.randomUUID(),f.activity(),"Our memory",List.of(key(f,f.member(),false),key(f,f.member(),true))));}
 @Test void createEditDeleteAndMediaArePrivate(){F f=fixture();Moment p=create(f);assertEquals(2,p.media().size());assertEquals(f.activity(),p.activityId());assertEquals("Our memory",service.get(p.id(),f.owner()).caption());assertFalse(service.get(p.id(),f.owner()).permissions().canEdit()==false);assertNotNull(service.mediaAccess(p.media().getFirst().id(),f.owner()).url());assertThrows(BusinessException.class,()->service.get(p.id(),f.outsider()));assertThrows(BusinessException.class,()->service.mediaAccess(p.media().getFirst().id(),f.outsider()));service.edit(p.id(),f.member(),new EditMoment("Edited",null));assertNull(service.get(p.id(),f.owner()).activityId());service.delete(p.id(),f.owner());assertThrows(BusinessException.class,()->service.get(p.id(),f.member()));assertThrows(BusinessException.class,()->service.mediaAccess(p.media().getFirst().id(),f.member()));verify(storage,never()).delete(any());}
 @Test void creationAndCommentRetryDoNotDuplicate(){F f=fixture();UUID command=UUID.randomUUID();var request=new CreateMoment(command,null,"Text only",List.of());assertEquals(command,service.create(f.group(),f.member(),request).id());service.create(f.group(),f.member(),request);assertEquals(1,service.feed(f.group(),f.owner(),null,null).items().size());UUID comment=UUID.randomUUID();service.addComment(command,f.owner(),new AddComment(comment,"Hello"));service.addComment(command,f.owner(),new AddComment(comment,"Hello"));assertEquals(1,service.get(command,f.owner()).commentCount());assertThrows(BusinessException.class,()->service.deleteComment(command,comment,f.member()));service.deleteComment(command,comment,f.owner());assertEquals(0,service.get(command,f.owner()).commentCount());}
 @Test void commentModerationAndGroupIsolation(){F f=fixture();Moment p=create(f);var c=service.addComment(p.id(),f.member(),new AddComment(UUID.randomUUID(),"Hi"));assertThrows(BusinessException.class,()->service.deleteComment(p.id(),c.id(),f.outsider()));service.deleteComment(p.id(),c.id(),f.owner());assertTrue(service.comments(p.id(),f.member(),null).items().isEmpty());F other=fixture();assertThrows(BusinessException.class,()->service.create(f.group(),f.member(),new CreateMoment(UUID.randomUUID(),other.activity(),"Wrong",List.of())));assertThrows(BusinessException.class,()->service.create(f.group(),f.member(),new CreateMoment(UUID.randomUUID(),null,"Wrong object",List.of(key(other,other.member(),false)))));assertThrows(BusinessException.class,()->service.create(f.group(),f.member(),new CreateMoment(UUID.randomUUID(),null,"Wrong uploader",List.of(key(f,f.owner(),false)))));}
 @Test void reactionIsIdempotentAndConcurrent()throws Exception{F f=fixture();Moment p=create(f);try(var pool=java.util.concurrent.Executors.newFixedThreadPool(3)){var jobs=List.of(pool.submit(()->service.react(p.id(),f.owner(),"👍")),pool.submit(()->service.react(p.id(),f.owner(),"👍")),pool.submit(()->service.react(p.id(),f.member(),"❤️")));for(var job:jobs)job.get(15,java.util.concurrent.TimeUnit.SECONDS);}assertEquals(2,service.get(p.id(),f.owner()).reactionCount());service.react(p.id(),f.member(),"😂");assertEquals(2,service.get(p.id(),f.owner()).reactionCount());service.react(p.id(),f.owner(),null);service.react(p.id(),f.owner(),null);assertEquals(1,service.get(p.id(),f.owner()).reactionCount());}
 @Test void albumsReferenceBytesAndDeleteSafely(){F f=fixture();Moment p=create(f);var a=service.saveAlbum(f.group(),f.owner(),new SaveAlbum(UUID.randomUUID(),f.activity(),"Album","Desc"),false);service.items(a.id(),f.owner(),p.media().stream().map(Media::id).toList(),true);service.items(a.id(),f.owner(),p.media().stream().map(Media::id).toList(),true);assertEquals(2,service.album(a.id(),f.member()).itemCount());assertNotNull(service.album(a.id(),f.member()).cover());assertEquals(2,service.albumMedia(a.id(),f.member(),null).items().size());assertThrows(BusinessException.class,()->service.items(a.id(),f.member(),List.of(p.media().getFirst().id()),false));service.saveAlbum(f.group(),f.owner(),new SaveAlbum(a.id(),null,"Renamed",""),true);service.items(a.id(),f.owner(),List.of(p.media().getFirst().id()),false);assertEquals(1,service.album(a.id(),f.owner()).itemCount());service.deleteAlbum(a.id(),f.owner());assertThrows(BusinessException.class,()->service.album(a.id(),f.owner()));assertNotNull(service.mediaAccess(p.media().getFirst().id(),f.owner()));verify(storage,never()).delete(any());}
 @Test void crossGroupAlbumLinksAndDeletedMomentAreRejected(){F f=fixture(),other=fixture();Moment p=create(other);var a=service.saveAlbum(f.group(),f.owner(),new SaveAlbum(UUID.randomUUID(),null,"A",""),false);assertThrows(BusinessException.class,()->service.items(a.id(),f.owner(),List.of(p.media().getFirst().id()),true));assertThrows(org.springframework.dao.DataIntegrityViolationException.class,()->db.update("INSERT INTO album_items(album_id,media_id,added_by) VALUES (?,?,?)",a.id(),p.media().getFirst().id(),f.owner()));Moment local=create(f);service.items(a.id(),f.owner(),List.of(local.media().getFirst().id()),true);service.delete(local.id(),f.member());assertEquals(0,service.album(a.id(),f.owner()).itemCount());}
 @Test void cursorPaginationAndActivityFiltering(){F f=fixture();for(int i=0;i<23;i++)service.create(f.group(),f.member(),new CreateMoment(UUID.randomUUID(),i==0?f.activity():null,"Post "+i,List.of()));var page=service.feed(f.group(),f.owner(),null,null);assertEquals(20,page.items().size());assertTrue(page.hasMore());assertEquals(3,service.feed(f.group(),f.owner(),null,page.nextBefore()).items().size());assertEquals(1,service.feed(f.group(),f.owner(),f.activity(),null).items().size());}
 @Test void rollbackHasNoPhantomAndCommitPublishesAuthorizedHint()throws Exception{F f=fixture();try(var peer=new RealtimeProbe(realtime,f.member(),"group:"+f.group())){new TransactionTemplate(transactions).executeWithoutResult(tx->{service.create(f.group(),f.owner(),new CreateMoment(UUID.randomUUID(),null,"Rollback",List.of()));assertTrue(peer.frames.isEmpty());tx.setRollbackOnly();});awaitDelivery();assertTrue(peer.frames.isEmpty());assertTrue(service.feed(f.group(),f.member(),null,null).items().isEmpty());service.create(f.group(),f.owner(),new CreateMoment(UUID.randomUUID(),null,"Committed",List.of()));assertNotNull(peer.await("MOMENT_CREATED"));}}
 @Test void revocationAndArchivedGroupsFailClosed(){F f=fixture();Moment p=create(f);db.update("UPDATE group_memberships SET status='LEFT',ended_at=now() WHERE group_id=? AND user_id=?",f.group(),f.member());assertThrows(BusinessException.class,()->service.get(p.id(),f.member()));assertThrows(BusinessException.class,()->service.mediaAccess(p.media().getFirst().id(),f.member()));db.update("UPDATE groups SET status='ARCHIVED' WHERE id=?",f.group());assertFalse(service.get(p.id(),f.owner()).permissions().canInteract());assertThrows(BusinessException.class,()->service.react(p.id(),f.owner(),"👍"));}
 @Test void mediaPolicyValidatesMimeExtensionSizeAndOwnership(){F f=fixture();assertThrows(BusinessException.class,()->uploads.presign(f.member(),new PresignUploadRequest(UploadCategory.MOMENT_VIDEO,"v.mov","video/quicktime",42,f.group().toString())));assertThrows(BusinessException.class,()->uploads.presign(f.member(),new PresignUploadRequest(UploadCategory.MOMENT_VIDEO,"v.mp4","video/mp4",52428801,f.group().toString())));String k=key(f,f.member(),false);when(storage.head(k)).thenReturn(new ObjectStorageService.ObjectMetadata("image/png",42,Map.of("declared-size","43")));assertThrows(BusinessException.class,()->service.create(f.group(),f.member(),new CreateMoment(UUID.randomUUID(),null,"Bad metadata",List.of(k))));assertTrue(service.feed(f.group(),f.owner(),null,null).items().isEmpty());}
 @Test void concurrentMediaCreateRetriesResolveOneCanonicalPost()throws Exception{F f=fixture();var request=new CreateMoment(UUID.randomUUID(),null,"Retry photo",List.of(key(f,f.member(),false)));try(var pool=java.util.concurrent.Executors.newFixedThreadPool(3)){var results=java.util.stream.IntStream.range(0,3).mapToObj(i->pool.submit(()->service.create(f.group(),f.member(),request))).toList();for(var result:results)assertEquals(request.clientRequestId(),result.get(15,java.util.concurrent.TimeUnit.SECONDS).id());}assertEquals(1,service.feed(f.group(),f.owner(),null,null).items().size());assertEquals(1,service.get(request.clientRequestId(),f.owner()).media().size());}
 @Test void restRoutesEnforceAuthenticationValidationAndPrivateProjection()throws Exception{
  F f=fixture();String route="/api/v1/groups/"+f.group()+"/moments";String bearer="Bearer "+jwt.generateAccessToken(f.member());
  http.perform(org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get(route)).andExpect(org.springframework.test.web.servlet.result.MockMvcResultMatchers.status().isUnauthorized());
  http.perform(org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post(route).header("Authorization",bearer).contentType("application/json").content("{\"caption\":\"missing command\",\"mediaKeys\":[]}")).andExpect(org.springframework.test.web.servlet.result.MockMvcResultMatchers.status().isBadRequest());
  Moment p=create(f);
  http.perform(org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get(route).header("Authorization",bearer)).andExpect(org.springframework.test.web.servlet.result.MockMvcResultMatchers.status().isOk()).andExpect(org.springframework.test.web.servlet.result.MockMvcResultMatchers.jsonPath("$.canCreate").value(true)).andExpect(org.springframework.test.web.servlet.result.MockMvcResultMatchers.jsonPath("$.items[0].media[0].storageKey").doesNotExist());
  http.perform(org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get("/api/v1/moment-media/"+p.media().getFirst().id()+"/access").header("Authorization","Bearer "+jwt.generateAccessToken(f.outsider()))).andExpect(org.springframework.test.web.servlet.result.MockMvcResultMatchers.status().is4xxClientError());
 }
}
